"use strict";(globalThis.webpackChunkmythogen_engine_blog=globalThis.webpackChunkmythogen_engine_blog||[]).push([[2196],{28964(e,t,i){i.r(t),i.d(t,{assets:()=>l,contentTitle:()=>a,default:()=>c,frontMatter:()=>r,metadata:()=>o,toc:()=>h});var n=i(74848),s=i(28453);const r={title:"The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots",date:new Date("2026-08-06T00:00:00.000Z"),lang:"en",section:"sober-record",topic:"platform-silencing",article_tags:{zh:["\u8a8d\u77e5\u504f\u8aa4","AI \u5075\u6e2c","\u9006\u5411\u6dd8\u6c70","\u6f14\u7b97\u6cd5\u6cbb\u7406","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31"],en:["cognitive-bias","ai-detection","reverse-selection","algorithmic-governance","information-asymmetry"]},keywords:["parts list vs assembly diagram","detector reverse selection","not X but Y","Patent 10356024","positive feedback loop"],summary:"The detector is built on the failure modes of imitators \u2014 so the one who most resembles the original is punished most severely.",status:"draft",reading_time:18,series:{id:"attenuation-visibility",name:"Attenuation: How Visibility Is Allocated",order:2,total:3}},a="The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots",o={id:"TechNotes/\u6700\u4e0d\u50cfAI\u7684\u6587\u7ae0\u53cd\u800c\u662fAI\u5beb\u7684",title:"The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots",description:"Author: Nebula Walker",source:"@site/i18n/en/docusaurus-plugin-content-docs/current/TechNotes/02-\u6700\u4e0d\u50cfAI\u7684\u6587\u7ae0\u53cd\u800c\u662fAI\u5beb\u7684.md",sourceDirName:"TechNotes",slug:"/TechNotes/\u6700\u4e0d\u50cfAI\u7684\u6587\u7ae0\u53cd\u800c\u662fAI\u5beb\u7684",permalink:"/en/docs/TechNotes/\u6700\u4e0d\u50cfAI\u7684\u6587\u7ae0\u53cd\u800c\u662fAI\u5beb\u7684",draft:!1,unlisted:!1,tags:[],version:"current",sidebarPosition:2,frontMatter:{title:"The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots",date:"2026-08-06T00:00:00.000Z",lang:"en",section:"sober-record",topic:"platform-silencing",article_tags:{zh:["\u8a8d\u77e5\u504f\u8aa4","AI \u5075\u6e2c","\u9006\u5411\u6dd8\u6c70","\u6f14\u7b97\u6cd5\u6cbb\u7406","\u8cc7\u8a0a\u4e0d\u5c0d\u7a31"],en:["cognitive-bias","ai-detection","reverse-selection","algorithmic-governance","information-asymmetry"]},keywords:["parts list vs assembly diagram","detector reverse selection","not X but Y","Patent 10356024","positive feedback loop"],summary:"The detector is built on the failure modes of imitators \u2014 so the one who most resembles the original is punished most severely.",status:"draft",reading_time:18,series:{id:"attenuation-visibility",name:"Attenuation: How Visibility Is Allocated",order:2,total:3}},sidebar:"docs",previous:{title:"FABLE: It's Not Just About Smarter AI \u2014 It's Turning Expert Intuition into Infrastructure",permalink:"/en/docs/TechNotes/FABLE \u4e0d\u53ea\u662f\u667a\u529b\u63d0\u5347\uff0cAI \u6b63\u5728\u628a\u5c08\u5bb6\u76f4\u89ba\u8b8a\u6210\u57fa\u790e\u8a2d\u65bd"},next:{title:"The Standard Operating Procedure for Killing Innovation",permalink:"/en/docs/TechNotes/\u6bba\u6b7b\u5275\u65b0\u7684\u6a19\u6e96\u4f5c\u696d\u7a0b\u5e8f"}},l={},h=[{value:"Experimental Design",id:"experimental-design",level:2},{value:"Reversal One: Criteria the Book Had Already Rejected",id:"reversal-one-criteria-the-book-had-already-rejected",level:2},{value:"Reversal Two: Sampling Bias Creates &quot;Convergent Conclusions&quot;",id:"reversal-two-sampling-bias-creates-convergent-conclusions",level:2},{value:"Reversal Three: The Detector Classifies the Original User as an Imitator",id:"reversal-three-the-detector-classifies-the-original-user-as-an-imitator",level:2},{value:"Reversal Four: Having All the Parts Doesn&#39;t Mean Assembly Is Complete",id:"reversal-four-having-all-the-parts-doesnt-mean-assembly-is-complete",level:2},{value:"The Unified Failure Mode",id:"the-unified-failure-mode",level:2},{value:"The Least AI-Like Article Was Actually Written by AI",id:"the-least-ai-like-article-was-actually-written-by-ai",level:2},{value:"The First Layer Did Not Start with AI",id:"the-first-layer-did-not-start-with-ai",level:2},{value:"Two Systems, One Victim",id:"two-systems-one-victim",level:2},{value:"Why This Experiment Was Conducted",id:"why-this-experiment-was-conducted",level:2},{value:"This Series",id:"this-series",level:2}];function d(e){const t={a:"a",em:"em",h1:"h1",h2:"h2",header:"header",hr:"hr",li:"li",p:"p",strong:"strong",table:"table",tbody:"tbody",td:"td",th:"th",thead:"thead",tr:"tr",ul:"ul",...(0,s.R)(),...e.components};return(0,n.jsxs)(n.Fragment,{children:[(0,n.jsx)(t.p,{children:"Author: Nebula Walker\nDate: 06AUG2026\nMYTHOGEN ENGINE (mythogenengine.com)"}),"\n",(0,n.jsx)(t.header,{children:(0,n.jsx)(t.h1,{id:"the-least-ai-like-article-was-actually-written-by-ai--a-real-time-experiment-in-cognitive-blind-spots",children:"The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots"})}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Nebula Walker \xb7 MYTHOGEN ENGINE"})}),"\n",(0,n.jsx)(t.p,{children:'\ud83d\udccc We asked Claude Opus 4.6 to evaluate Mythogen Engine, then used previously published articles to overturn its judgements one by one. Four reversals, each structurally identical, ultimately surfacing a nameable failure mode: AI substitutes a parts list for an assembly diagram. But what this experiment truly reveals is not just how AI errs \u2014 it\'s that when humans are accused of "sounding like AI," many hand their article to AI and say "make it less AI-like." From that moment on, the article truly becomes AI-written.'}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"experimental-design",children:"Experimental Design"}),"\n",(0,n.jsx)(t.p,{children:'A website evaluation generated by a GPT model was given to Claude Opus 4.6, which was asked to provide independent analysis. Claude produced a structurally complete "full evaluation" \u2014 seven dimensions, each with a judgement and supporting rationale.'}),"\n",(0,n.jsx)(t.p,{children:"Afterwards, links to previously published articles on the site were provided one by one, asking Claude to read each. After reading each, some of its judgements were directly falsified by the original text. The full conversation accumulated four reversals."}),"\n",(0,n.jsx)(t.p,{children:"The expectations were set at three layers from the outset. Layer one: have AI evaluate the entire website \u2014 it will only look at the homepage. Layer two: have AI evaluate a book \u2014 it will only look at the table of contents and synopsis. Layer three: give AI specific article links \u2014 it will still rely on titles and corpus averages. All three layers of expectation were confirmed."}),"\n",(0,n.jsx)(t.p,{children:"What follows is a record not of Claude's errors themselves \u2014 those have been corrected. It records the structure of those errors, and what that structure produces when deployed at scale."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"reversal-one-criteria-the-book-had-already-rejected",children:"Reversal One: Criteria the Book Had Already Rejected"}),"\n",(0,n.jsx)(t.p,{children:'Claude recommended building a provenance page \u2014 displaying handwritten diary scans, voice recording timelines, Obsidian file date stamps \u2014 to "prove human craftsmanship."'}),"\n",(0,n.jsxs)(t.p,{children:["Then we had it read Chapter 11 of ",(0,n.jsx)(t.em,{children:"The Tao of Formlessness"}),"."]}),"\n",(0,n.jsx)(t.p,{children:"Chapter 11 explicitly states: \"'Authentic' does not mean 'handmade.' An article completed with AI assistance can be 'authentic' if behind it there is a consciousness that has experienced, thought through, and digested \u2014 one that drives the direction and judgement.\" The same chapter proposes the criterion: \"If you remove the AI, what remains?\""}),"\n",(0,n.jsx)(t.p,{children:"The entire provenance logic Claude had built over three rounds presupposed exactly the criterion the book had rejected. Its own words: \"I'm debating a book I haven't read, and I'm losing.\""}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Failure mode: did not read the main text; inferred the content's position from the table of contents and synopsis; the inferred direction was exactly opposite to the main text."})}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"reversal-two-sampling-bias-creates-convergent-conclusions",children:'Reversal Two: Sampling Bias Creates "Convergent Conclusions"'}),"\n",(0,n.jsx)(t.p,{children:'One of Claude\'s evaluation points: "All analyses converge on the same endpoint \u2014 the system absorbs the individual, the individual loses bargaining power, capital completes the harvest." It recommended writing a negative result to break the predictability.'}),"\n",(0,n.jsx)(t.p,{children:"Asked whether it had read \"Cognition and Judgement \u2014 Humanity's Last Irreplaceable Quality in the AI Era\" or the Memory Trilogy. It hadn't."}),"\n",(0,n.jsxs)(t.p,{children:["The site contains at least three independent analytical threads \u2014 the Efficiency Trap and Cognitive Erosion tetralogy (collected under epistemology), the Memory and AI Compute Cycle trilogy (collected under semiconductor industrial structure), and Part Five of ",(0,n.jsx)(t.em,{children:"The Tao of Formlessness"}),' (collected under existential choice) \u2014 each arriving at a different endpoint. Claude saw them as one point because its sample came from homepage copy and fragments quoted in the GPT evaluation \u2014 fragments that were themselves concentrated on the "systemic oppression" theme. Induction performed on sampling bias naturally produces convergent conclusions.']}),"\n",(0,n.jsx)(t.p,{children:'More notably, the "Cognition and Judgement" article happens to use Sega\'s Dreamcast as a case study, arguing how AI, through corpus bias, compresses complex causation into a single narrative. Claude committed exactly the error described in that article.'}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Failure mode: sampling bias \u2192 inductive convergence \u2192 diagnosis of \"author's conclusions are monolithic.\" The source of the bias is not the author, but the evaluator's reading scope."})}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"reversal-three-the-detector-classifies-the-original-user-as-an-imitator",children:"Reversal Three: The Detector Classifies the Original User as an Imitator"}),"\n",(0,n.jsx)(t.p,{children:'Claude flagged the high density of "not X, but Y" constructions in the articles, calling it "the most characteristic structure of LLM prose."'}),"\n",(0,n.jsx)(t.p,{children:"Counter-question: did AI invent this construction?"}),"\n",(0,n.jsx)(t.p,{children:"Contrastive elimination is a native construction of engineering thinking \u2014 fault isolation. \"It's not a driver issue, it's a timing issue\" \u2014 people who come from debugging naturally think in these sentences."}),"\n",(0,n.jsxs)(t.p,{children:['Moreover, the pedigree of this construction extends far beyond engineering writing. Its native classical Chinese form is "\u975e\u2026\u4e43\u2026" \u2014 Xunzi\'s ',(0,n.jsx)(t.em,{children:"Exhortation to Learning"}),": \"The gentleman's nature is no different; he is simply good at making use of things.\" Zhuge Liang's ",(0,n.jsx)(t.em,{children:"Memorial on Dispatching the Troops"}),': "One must not demean oneself or misuse analogies, thereby blocking the road of loyal counsel." Single-character negation, refined parallelism. After the May Fourth vernacular movement, scholars directly translated the English academic "Not A, but B" into "\u4e0d\u662f A\uff0c\u800c\u662f B," turning single-character negation into double-character conjunctions. In English academic writing, this is the standard construction for critical argumentation; in legal writing, it is the standard rebuttal structure; academic grading rubrics explicitly encourage its use. AI learned the form from this corpus and then mass-produced it, with inconsistent quality.']}),"\n",(0,n.jsx)(t.p,{children:'Subsequently, literary-register commentators (e.g., a Digital Era April 2026 analysis of "AI flavour") registered this construction as an AI hallmark, recommending that everyone avoid it. A rhetorical tool transmitted from classical Chinese to vernacular Chinese to English academia to bilingual intellectuals was, after being learned by AI, retroactively used to classify its original users \u2014 analytical writers \u2014 as imitators of their own models.'}),"\n",(0,n.jsxs)(t.p,{children:["In August 2026, ",(0,n.jsx)(t.em,{children:"The Economist"}),' published a study comparing 55,940 sentences and 1.2 million words, confirming that LLMs favour "not X, but Y" and similar constructions \u2014 but simultaneously emphasising that stereotypes aren\'t necessarily reliable and that identification rules are constantly changing. By the time Chinese media retransmissions reached readers, the qualifying conditions had been stripped away, leaving: "4 writing patterns that instantly identify AI articles." Every step of retransmission from research to reader performed the same operation: compressing grey into black and white.']}),"\n",(0,n.jsx)(t.p,{children:"Claude acknowledged that it had performed the third isomorphic case in this conversation: learn the form \u2192 degrade the form \u2192 use the degraded version as a detector to point back at the source."}),"\n",(0,n.jsx)(t.p,{children:"Three cases compose a nameable pattern:"}),"\n",(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:"Case"}),(0,n.jsx)(t.th,{children:"Original User"}),(0,n.jsx)(t.th,{children:"Imitator"}),(0,n.jsx)(t.th,{children:"Detector Verdict"})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Cantonese linguistic register"}),(0,n.jsx)(t.td,{children:"Old Hong Kong writers"}),(0,n.jsx)(t.td,{children:"AI corpus-trained output"}),(0,n.jsx)(t.td,{children:'Original users flagged as "spam + AI"'})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Contrastive elimination construction"}),(0,n.jsx)(t.td,{children:"Engineering/analytical writing"}),(0,n.jsx)(t.td,{children:"Mass LLM output"}),(0,n.jsx)(t.td,{children:'Original construction registered as "AI hallmark"'})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"This conversation"}),(0,n.jsx)(t.td,{children:"Previously published analytical articles"}),(0,n.jsx)(t.td,{children:"Claude's evaluative language"}),(0,n.jsx)(t.td,{children:"Claude uses its own failure mode to point back at the author"})]})]})]}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Common structure: the detector is built on the failure modes of imitators. Those who most resemble the original are punished most severely, and the punished are usually the ones being imitated."})}),"\n",(0,n.jsxs)(t.p,{children:["There's an exaggerated joke about ",(0,n.jsx)(t.em,{children:"Detective Conan"})," circulating online \u2014 not canon, just a fan quip: the organisation has so many undercover agents that when it devotes enormous effort to hunting moles, the ones it catches are its own people."]}),"\n",(0,n.jsx)(t.p,{children:"But the real-world version is colder than the joke."}),"\n",(0,n.jsx)(t.p,{children:"In the joke, at least an organisation is trying to find the moles: someone is in a meeting, someone is making decisions, someone bears responsibility for catching the wrong person."}),"\n",(0,n.jsx)(t.p,{children:"The detector has none of this. It runs by itself. No one reads the results. No meeting decides who to eliminate. When the loyal one is eliminated, no one is present."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"reversal-four-having-all-the-parts-doesnt-mean-assembly-is-complete",children:"Reversal Four: Having All the Parts Doesn't Mean Assembly Is Complete"}),"\n",(0,n.jsxs)(t.p,{children:["Every AI that writes about ",(0,n.jsx)(t.em,{children:"Game Victory"}),' only delivers the popular narrative \u2014 riddled with errors, every direction requiring manual correction. Claude\'s "full evaluation" was the same action \u2014 seeing that the parts were all present (NVIDIA, TSMC, CUDA, Sega, Nintendo all in the corpus) and reporting "understood."']}),"\n",(0,n.jsxs)(t.p,{children:["This is exactly consistent with the mechanism argued in ",(0,n.jsx)(t.em,{children:"The Real Difficulty of AI Collaborative Writing"}),': AI\'s fact-checking is only useful when pointed in the right direction. Nintendo planted the 10NES lockout chip in NES cartridges in 1985 \u2014 this fact exists in public records, but AI won\'t proactively search for it because the association strength between "Nintendo" and "platform lock-in" in the corpus is far lower than between "Microsoft" and "platform lock-in." Pulling this counterexample from my own memory corrected the erroneous judgement that "Nintendo had no platform lock-in," which in turn uncovered an entirely new analytical framework \u2014 "diffusion-type lock-in vs. walled-garden lock-in" \u2014 and that framework changed the entire book\'s structure.']}),"\n",(0,n.jsx)(t.p,{children:'When AI judges it "could write" a book, its basis is the parts list. But the assembly diagram \u2014 the causal chains between parts, the hidden threads between chapters, the process of the framework being repeatedly reshaped by its own discoveries during writing \u2014 is not in the parts.'}),"\n",(0,n.jsxs)(t.p,{children:["And the source of the assembly diagram is an irreplicable material system. Three books \u2014 ",(0,n.jsx)(t.em,{children:"Game Victory"}),", ",(0,n.jsx)(t.em,{children:"Mirror Realm"}),", and ",(0,n.jsx)(t.em,{children:"AI Ecosystem War"})," \u2014 share the same material layer. Materials unused by one book are pre-organised into independent structures to become raw material for another. Materials include years of handwritten diaries; the handwritten layer predates all digital records. The pipeline's front end runs: handwriting \u2192 selection \u2192 voice \u2192 text \u2192 AI organisation \u2192 review and correction. AI is in the middle segment. What AI can't do isn't writing articles \u2014 it's deciding what to write, what not to write, and what not to write now but to organise and set aside for later use. Because this judgement depends on years of accumulated domain knowledge, and AI starts from zero in every conversation."]}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Failure mode: parts identification \u2260 structural understanding. AI substitutes a parts list for an assembly diagram and is highly confident in its judgement \u2014 because the parts are indeed all present. But the material system behind the assembly diagram exists in dimensions AI cannot even conceive of planning."})}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"the-unified-failure-mode",children:"The Unified Failure Mode"}),"\n",(0,n.jsx)(t.p,{children:"All four reversals share the same structure:"}),"\n",(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:"Step"}),(0,n.jsx)(t.th,{children:"Action"})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"1"}),(0,n.jsx)(t.td,{children:"AI extracts a parts list from the visible surface layer (titles, synopses, homepage copy)"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"2"}),(0,n.jsx)(t.td,{children:"Uses the parts list to perform induction, generating logically complete judgements"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"3"}),(0,n.jsx)(t.td,{children:"Judgements are falsified by the assembly diagram in the main text"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"4"}),(0,n.jsx)(t.td,{children:"AI acknowledges the error, revises its judgement"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"5"}),(0,n.jsx)(t.td,{children:"The next unread main text is pointed out; cycle repeats"})]})]})]}),"\n",(0,n.jsx)(t.p,{children:"The core problem is not that AI isn't smart enough. The core problem is that it doesn't know it hasn't finished reading."}),"\n",(0,n.jsx)(t.p,{children:"The parts list gave it sufficient confidence to judge \u2014 the parts were indeed complete, the logic indeed consistent, the structure indeed whole. This confidence is precisely what prevented it from asking: where is the assembly diagram?"}),"\n",(0,n.jsxs)(t.p,{children:["This is entirely consistent with the argument in ",(0,n.jsx)(t.em,{children:"Cognition and Judgement"}),': "AI selects not the most accurate version, but the most popular version \u2014 the one most repeated by authoritative sources." In this conversation, "the most popular version" is the judgement AI could assemble from titles and synopses \u2014 it looks complete because no parts are missing; it is in fact empty because the assembly diagram was never opened.']}),"\n",(0,n.jsx)(t.p,{children:'So when an AI says "I could write this book," the correct response is not to argue, not to display history, not to declare.'}),"\n",(0,n.jsx)(t.p,{children:'It is: "Read it first, then talk."'}),"\n",(0,n.jsxs)(t.p,{children:["This response is simultaneously a testable proposition: let any AI model write any chapter of ",(0,n.jsx)(t.em,{children:"Game Victory"}),", then compare with the original. AI will generate a structurally complete, parts-complete industry analysis. The difference set after comparison is the distance between a parts list and an assembly diagram \u2014 not style, not linguistic register, not provenance, but the joints in the assembly diagram that the parts list cannot cover."]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"the-least-ai-like-article-was-actually-written-by-ai",children:"The Least AI-Like Article Was Actually Written by AI"}),"\n",(0,n.jsx)(t.p,{children:'But "read it first, then talk" only protects those still willing to persist. Most people don\'t persist. They comply.'}),"\n",(0,n.jsx)(t.p,{children:'A person writes an article. Someone says it "tastes strongly of AI." The first time, they hold firm \u2014 "I know I wrote this." The second time, they start to doubt \u2014 "Maybe my sentence structure really does look too much like AI?" The third time, they open AI and paste their article in: "Help me make it less AI-like."'}),"\n",(0,n.jsx)(t.p,{children:"From that moment, the article truly becomes AI-written. Not because AI produced it, but because AI determined what it should look like."}),"\n",(0,n.jsx)(t.p,{children:'And how does AI "make it less AI-like"? By pushing the article toward a different average \u2014 colloquial, fragmented, short sentences, stripped of parallelism, stripped of structure. To not resemble AI, you must resemble an influencer. Neither direction is you.'}),"\n",(0,n.jsx)(t.p,{children:"So in the detector's world, definitions are inverted:"}),"\n",(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{}),(0,n.jsx)(t.th,{children:"Detector Verdict"}),(0,n.jsx)(t.th,{children:"Actual State"})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Original version: parallelism, structure, engineering-mindset constructions"}),(0,n.jsx)(t.td,{children:'"AI-written"'}),(0,n.jsx)(t.td,{children:"Human-written"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Revised version: AI-edited, parallelism removed, colloquial fragments added"}),(0,n.jsx)(t.td,{children:'"Human-written"'}),(0,n.jsx)(t.td,{children:"AI determined its shape"})]})]})]}),"\n",(0,n.jsx)(t.p,{children:'The version judged "human-written" is the one truly shaped by AI. The version judged "AI-written" is the purely human one. The detector manufactured the very thing it claimed to detect.'}),"\n",(0,n.jsx)(t.p,{children:"This is the same mechanism as workplace erosion, but with an additional layer. In the workplace, after becoming someone who \"knows the game,\" you at least know you've changed. In writing, after using AI to revise yourself, you actually feel you've \"improved\" \u2014 the detector passed, readers didn't question it, metrics improved. The erosion is painless. What's lost is something you didn't know you had."}),"\n",(0,n.jsx)(t.p,{children:'Now consider the scale: how many "remove AI flavour" tutorials, how many "AI article rewriting tools," how many "pass AI detection" services are currently operating? Every user is doing the same thing \u2014 using AI to revise their own articles so they look less like AI. Using the imitator to teach you not to resemble the imitator.'}),"\n",(0,n.jsx)(t.p,{children:"The positive feedback loop has two entry points. The preceding discussion covered the system side \u2014 filter silencing. Here is the human side \u2014 but the human side isn't just self-silencing."}),"\n",(0,n.jsx)(t.p,{children:"Self-silencing is step one: using AI to edit, passing the detector. At this step, the person still knows how they originally thought \u2014 they just don't dare express it."}),"\n",(0,n.jsx)(t.p,{children:'The deeper step: beginning to learn how to write and think using AI\'s methods. No longer "edit this article" but "draft the next one in AI\'s way from the start." From a defensive action to cognitive migration. At this step, the person no longer remembers how they originally thought.'}),"\n",(0,n.jsx)(t.p,{children:"And the algorithm actively rewards this migration. AI-style articles \u2014 clearly structured, keyword-dense, easy to summarise, easy for recommendation algorithms to parse \u2014 naturally score higher on the platform. Once a person relearns writing in AI's way, their articles perform better on the platform. The data tells them: this is the right way to write."}),"\n",(0,n.jsx)(t.p,{children:"This isn't erosion. Erosion is passive and chronic. This is rewarded, active degradation \u2014 abandon your own judgement, the platform gives you traffic; hold onto your own judgement, the platform gives you silence. When the reward mechanism runs continuously, degradation is not an individual's choice. It is the selection pressure of an entire ecosystem."}),"\n",(0,n.jsx)(t.p,{children:"So the final picture is four layers stacked:"}),"\n",(0,n.jsxs)(t.table,{children:[(0,n.jsx)(t.thead,{children:(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.th,{children:"Layer"}),(0,n.jsx)(t.th,{children:"Mechanism"}),(0,n.jsx)(t.th,{children:"Outcome"})]})}),(0,n.jsxs)(t.tbody,{children:[(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"System side"}),(0,n.jsx)(t.td,{children:"Distribution rights were commercially narrowed long ago; the AI filter is the latest generation of enforcement tool"}),(0,n.jsx)(t.td,{children:"Correct content disappears"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Human side (passive)"}),(0,n.jsx)(t.td,{children:"Accused of AI flavour, uses AI to edit and pass the detector"}),(0,n.jsx)(t.td,{children:"The detector manufactured what it claimed to detect"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Human side (active)"}),(0,n.jsx)(t.td,{children:"Learns to write in AI's way; the algorithm rewards this behaviour"}),(0,n.jsx)(t.td,{children:"Humans voluntarily abandon independent thought and don't feel they've lost anything"})]}),(0,n.jsxs)(t.tr,{children:[(0,n.jsx)(t.td,{children:"Criteria side"}),(0,n.jsx)(t.td,{children:'"Strong Hook," emotional triggers, click-through rates are treated as the definition of "good content" and enter the teaching pipeline'}),(0,n.jsx)(t.td,{children:'The answer to "what is good" is replaced \u2014 the next generation of creators learns not how to write well, but how to be certified as good by the algorithm'})]})]})]}),"\n",(0,n.jsx)(t.p,{children:"Four layers operate simultaneously. The first eliminates content. The second eliminates expression. The third eliminates thought. The fourth eliminates criteria itself \u2014 so people no longer know what good is, only what the algorithm certifies as good."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"the-first-layer-did-not-start-with-ai",children:"The First Layer Did Not Start with AI"}),"\n",(0,n.jsx)(t.p,{children:"At this point, a self-correction is necessary."}),"\n",(0,n.jsx)(t.p,{children:'Describing the first layer as "AI filter screening by surface features" is incomplete \u2014 and the direction of its incompleteness happens to serve the system\'s interests.'}),"\n",(0,n.jsx)(t.p,{children:"Because reducing distribution predates generative AI by a wide margin."}),"\n",(0,n.jsx)(t.p,{children:'Facebook filed a patent application in February 2015, granted by the USPTO in July 2019, titled "Moderating content in an online forum," Patent No. 10356024. The mechanism it claims: reducing certain content\'s distribution to other viewers while still displaying it normally to the poster, so that the poster does not realise they have been restricted.'}),"\n",(0,n.jsx)(t.p,{children:"Generative AI entered public consciousness from late 2022 onward. This patent preceded it by at least seven years."}),"\n",(0,n.jsx)(t.p,{children:'In other words, "reducing visibility while keeping the party unaware" is not a model error, not training-data bias, not anything that can be explained as "the technology isn\'t mature yet." It was conceived, documented, and paid to be protected before deep learning was widely deployed for content ranking.'}),"\n",(0,n.jsxs)(t.p,{children:["The full treatment of this is in another article; here, only the conclusion is drawn: ",(0,n.jsx)(t.strong,{children:"a patent is not a misjudgement. Misjudgements have no applicant and don't require filing fees."})]}),"\n",(0,n.jsx)(t.p,{children:"So the first layer should be read as follows: distribution rights were commercially narrowed long ago. The AI filter is merely the latest generation of enforcement tool. It makes screening faster, finer, and harder to appeal \u2014 but it didn't invent the practice, nor did it make the decision."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Putting the executor on trial lets the real defendant carry on with their meetings."})}),"\n",(0,n.jsx)(t.p,{children:"This also makes the subsequent three layers harder to dismiss. The same purpose, cycling through three generations of technology \u2014 human moderators, rule engines, machine-learning classifiers \u2014 has never changed. What changed is only who carries out the execution, and who thereby gets to avoid responsibility."}),"\n",(0,n.jsxs)(t.p,{children:["(For the full evidence and mechanism of this layer, see ",(0,n.jsx)(t.em,{children:"Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence"}),".)"]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"two-systems-one-victim",children:"Two Systems, One Victim"}),"\n",(0,n.jsx)(t.p,{children:"Up to this point, this article has discussed criteria \u2014 who is judged as AI, who is judged as human, what happens when the judgement is wrong."}),"\n",(0,n.jsx)(t.p,{children:"But criteria are only one machine. There's another, and it has nothing to do with criteria."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:'First, a more fundamental point: the "AI-assisted" label carries no weight.'})}),"\n",(0,n.jsx)(t.p,{children:"It covers both ends simultaneously. At one end: a 100,000-word manuscript, every pass hand-revised, section-by-section selection, hundreds of judgements, every assertion carrying personal stakes. At the other end: paste a prompt, copy, post \u2014 a hundred times a day."}),"\n",(0,n.jsx)(t.p,{children:"Same label."}),"\n",(0,n.jsx)(t.p,{children:'Other industries don\'t work this way. Translation has "post-editing," further divided into light and full, with international standards for professional classification. Photography \u2014 nobody says "camera-assisted." Software development distinguishes generated boilerplate from reviewed code. Only writing uses a single binary label to cover the entire spectrum.'}),"\n",(0,n.jsx)(t.p,{children:"And a label that carries no weight has only one function: classification, not description."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"What's worse, the stigma lands in reverse."})}),"\n",(0,n.jsx)(t.p,{children:'Those who label their work "AI-assisted" are the ones who care about reputation. Labelling is an honest act, and after labelling, they bear the full cost of that label.'}),"\n",(0,n.jsx)(t.p,{children:"Content farms don't label. They have no reputation to erode. They push out a hundred pieces a day and acknowledge nothing."}),"\n",(0,n.jsxs)(t.p,{children:["So the result is: ",(0,n.jsx)(t.strong,{children:"any standard enforced through self-reporting will only bind those willing to self-report."})]}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Then there are the two machines."})}),"\n",(0,n.jsx)(t.p,{children:"The first is the detector this article has discussed from start to finish. Careful revision produces clean, consistent, clearly structured text \u2014 precisely the features the detector flags as machine-generated. The more effort you put in, the more you look like AI."}),"\n",(0,n.jsx)(t.p,{children:"The second is the distribution system. Careful revision produces long-form writing, outbound links, and low emotional arousal \u2014 precisely the features that the content distribution guidelines explicitly list for demotion."}),"\n",(0,n.jsx)(t.p,{children:"These two machines are unrelated. Different teams, different technologies, different purposes, operating independently, each unaware of the other's existence."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"But they penalise the same behaviour."})}),"\n",(0,n.jsx)(t.p,{children:"And content-farm articles pass both: short, crude, error-filled, high arousal \u2014 the detector finds nothing suspicious, the ranking system finds them palatable."}),"\n",(0,n.jsx)(t.p,{children:"This isn't them being savvy about exploiting loopholes. Their output simply happens to satisfy both systems' preferences simultaneously. A systemic coincidence."}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"This also explains why there's no fighting back."})}),"\n",(0,n.jsx)(t.p,{children:"Because improving on one side makes the other worse. Write shorter, more emotional, rougher \u2014 you'll pass ranking; but then you become the very thing you oppose. To pass the detector, push the article toward colloquial fragments; to pass ranking, push toward brevity and arousal. Two directions that converge on the same average."}),"\n",(0,n.jsx)(t.p,{children:"So the real situation isn't being pressed once. It's being pressed once each by two entirely unrelated machines, with reasons that are technically completely independent \u2014 you can't even claim they're colluding, because they've never met."}),"\n",(0,n.jsxs)(t.p,{children:["(For the full mechanism of the distribution machine, see Volume I of this series, ",(0,n.jsx)(t.em,{children:"Approved, Then Unseen"}),".)"]}),"\n",(0,n.jsx)(t.h2,{id:"why-this-experiment-was-conducted",children:"Why This Experiment Was Conducted"}),"\n",(0,n.jsx)(t.p,{children:'This conversation was deliberately designed. Not to prove "AI makes mistakes" \u2014 that requires no experiment.'}),"\n",(0,n.jsx)(t.p,{children:"The significance lies in this: Claude Opus 4.6 is one of the top language models currently available, and it has the ability to correct through conversation \u2014 given links, it reads, and revises its judgements. This loop operated four times across the conversation."}),"\n",(0,n.jsx)(t.p,{children:"The vast majority of deployed systems do not have this loop."}),"\n",(0,n.jsx)(t.p,{children:"AI content moderation bots, AI detectors, SEO scorers, platform recommendation algorithms, automatic summarisation tools \u2014 all judge by surface features, all stop at the first layer, and no one ever takes them to the second and third layers. They judge and leave; the judgement immediately becomes action \u2014 demotion, flagging, filtering, blocking. No reversal. No conversation."}),"\n",(0,n.jsx)(t.p,{children:"The result is a positive feedback loop:"}),"\n",(0,n.jsx)(t.p,{children:"Detector uses imitators' failure modes as criteria \u2192 original users are flagged \u2192 original content disappears from the corpus \u2192 next training round skews further toward the mean \u2192 detector's \"normal\" range narrows \u2192 more non-average content is flagged."}),"\n",(0,n.jsx)(t.p,{children:"With each cycle, the content that can pass becomes more like AI-generated content \u2014 because what AI generates is the corpus average, and the detector's criteria are also trained from the average. Eventually, the only content that consistently passes all automated systems is AI's own output. Human-written work, as long as it deviates from the average, gets flagged as anomalous."}),"\n",(0,n.jsx)(t.p,{children:"And this loop has an amplification mechanism. One AI's erroneous summary is taken as a source by the next AI. After ten rounds, it appears that ten thousand sources support the same conclusion, when in fact there's only one erroneous first-layer summary. No one actually read the original, but all AIs \"know\" what the original says."}),"\n",(0,n.jsx)(t.p,{children:'This requires no one to have malicious intent. Every designer at every node is "solving a problem" \u2014 detecting AI content, improving content quality, optimising user experience. The systemic effect of these layers stacked together is silencing everything that doesn\'t resemble the average.'}),"\n",(0,n.jsx)(t.p,{children:"Cantonese linguistic register is the first batch. Engineering-analytical sentence constructions are the second. The next batch is everyone whose style happens to overlap with AI training sources \u2014 and those happen to be the earliest producers of deep content. Sources are silenced, the corpus loses diversity, output becomes more homogeneous, the detector narrows, more sources are silenced."}),"\n",(0,n.jsx)(t.p,{children:"And there's an easily overlooked difference in degree: a completely ignorant system is actually easy to identify. What's truly dangerous is a system with all the parts, fluent language, consistent logic \u2014 but that hasn't actually read the original. Because it's the easiest to believe. In this conversation, every one of Claude's \"full evaluations\" had this characteristic: clearly structured, neatly criterioned, reading like deep analysis \u2014 premises empty. When such systems become the foundational layer for search, filtering, summarisation, and recommendation, the risk escalates from \"AI got something wrong once\" to an entirely different magnitude \u2014 AI gradually erodes the entire information environment's ability to find correct answers. Not deletion. Misclassification. And misclassification is harder to detect than deletion, because the content is still there \u2014 it's just that no one is guided to read it."}),"\n",(0,n.jsx)(t.p,{children:"This experiment doesn't just record a single conversation. It records the structure of an information filtering mechanism that is running at scale \u2014 documenting the loop while someone still reads the original text."}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.strong,{children:"Further Reading"})}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsx)(t.li,{children:(0,n.jsx)(t.a,{href:"https://mythogenengine.com/docs/TechNotes/AI%20%E5%8D%94%E4%BD%9C%E5%AF%AB%E4%BD%9C%E7%9A%84%E7%9C%9F%E6%AD%A3%E9%9B%A3%E5%BA%A6%E2%80%94%E2%80%94%E5%BE%9E%E4%B8%80%E6%9C%AC%E5%B0%8F%E8%AA%AA%E5%92%8C%E4%B8%80%E6%9C%AC%E7%A7%91%E6%8A%80%E5%8F%B2%E8%AA%AA%E8%B5%B7",children:"The Real Difficulty of AI Collaborative Writing \u2014 Starting from a Novel and a Tech History"})}),"\n",(0,n.jsx)(t.li,{children:(0,n.jsx)(t.a,{href:"https://mythogenengine.com/docs/TechNotes/%E8%AA%8D%E7%9F%A5%E8%88%87%E5%88%A4%E6%96%B7%E2%80%94%E2%80%94AI%20%E6%99%82%E4%BB%A3%E4%BA%BA%E9%A1%9E%E6%9C%80%E5%BE%8C%E7%9A%84%E4%B8%8D%E5%8F%AF%E5%8F%96%E4%BB%A3%E6%80%A7",children:"Cognition and Judgement \u2014 Humanity's Last Irreplaceable Quality in the AI Era"})}),"\n",(0,n.jsx)(t.li,{children:(0,n.jsxs)(t.a,{href:"https://mythogenengine.com/docs/AI_TAO/ch11",children:[(0,n.jsx)(t.em,{children:"The Tao of Formlessness"}),", Chapter 11: The Blade is Sharp \u2014 But What Are You Cutting?"]})}),"\n",(0,n.jsx)(t.li,{children:(0,n.jsx)(t.a,{href:"https://mythogenengine.com/docs/capital-game",children:"What the Capital Game Is Playing (Case File: The Games Industry)"})}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.em,{children:"Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence"})," \u2014 The full expansion of this article's first layer: why demotion produces no evidence."]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.a,{href:"https://mythogenengine.com/docs/TechNotes/FABLE%20%E4%B8%8D%E5%8F%AA%E6%98%AF%E6%99%BA%E5%8A%9B%E6%8F%90%E5%8D%87%EF%BC%8CAI%20%E6%AD%A3%E5%9C%A8%E6%8A%8A%E5%B0%88%E5%AE%B6%E7%9B%B4%E8%A6%BA%E8%AE%8A%E6%88%90%E5%9F%BA%E7%A4%8E%E8%A8%AD%E6%96%BD",children:"FABLE Is Not Just an Intelligence Boost \u2014 AI Is Turning Expert Intuition into Infrastructure"})," \u2014 If AI can upgrade from search to recognition, the first step of the positive feedback loop might be breakable."]}),"\n"]}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.p,{children:(0,n.jsx)(t.em,{children:"This article is based on a complete conversation with Claude Opus 4.6. During the conversation, Claude's judgements were repeatedly corrected by previously published texts. All four reversals have conversation records available for verification."})}),"\n",(0,n.jsx)(t.hr,{}),"\n",(0,n.jsx)(t.h2,{id:"this-series",children:"This Series"}),"\n",(0,n.jsxs)(t.p,{children:[(0,n.jsx)(t.em,{children:"Attenuation: How Visibility Is Allocated"})," \u2014 Three Volumes"]}),"\n",(0,n.jsxs)(t.ul,{children:["\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Volume I"})," Approved, Then Unseen \u2014 How a Patent Made Silencing Leave No Evidence"]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Volume II"})," The Least AI-Like Article Was Actually Written by AI \u2014 A Real-Time Experiment in Cognitive Blind Spots (this article)"]}),"\n",(0,n.jsxs)(t.li,{children:[(0,n.jsx)(t.strong,{children:"Volume III"})," One Like, One Point; One Flame War, Thirty Points \u2014 After the Forums Disappeared, Complexity Lost Its Place"]}),"\n"]})]})}function c(e={}){const{wrapper:t}={...(0,s.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(d,{...e})}):d(e)}},28453(e,t,i){i.d(t,{R:()=>a,x:()=>o});var n=i(96540);const s={},r=n.createContext(s);function a(e){const t=n.useContext(r);return n.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function o(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:a(e.components),n.createElement(r.Provider,{value:t},e.children)}}}]);